import{itemExpansionProfile,expandedItemAddress}from'./item-expansion.js';
// Select native item layouts using sequential IDs, names and bounded pointers.
import{decodeCreatureText}from'./expanded-form-native.js';
const trusted=new WeakMap();
export function discoverItemTable(r){const base=r.ptr(0x1c8);if(!r.valid(base,44))return null;const options=[{format:'classic',id:14,name:0,description:20,price:16,priceSize:2},{format:'pointer-name',id:4,name:20,description:12,price:0,priceSize:4}],found=[];
 for(const p of options){let count=0,last=0,empty=0;const validIds=[];for(;count<4096&&r.valid(base+count*44,44);count++){const at=base+count*44;if(r.bytes.subarray(at,at+44).every(v=>v===0)){if(++empty>64)break;continue;}empty=0;const nameAt=p.format!=='pointer-name'?at:r.ptr(at+p.name),name=r.valid(nameAt,14)?decodeCreatureText(r.bytes,nameAt,p.format!=='pointer-name'?14:40):'',id=r.u16(at+p.id),desc=r.ptr(at+p.description),blank=p.format!=='pointer-name'&&id===0&&/^\?+$/.test(name);if(!r.valid(nameAt,1)||!r.bytes.slice(nameAt,nameAt+(p.format!=='pointer-name'?14:40)).includes(255)||!r.valid(desc,1))break;if(p.format!=='pointer-name'&&(id>=4096||r.u8(at+26)>5||count<2&&id!==count))break;if(p.format==='pointer-name'&&(!name||r.u32(at)>999999||!r.valid(r.ptr(at+36),4)||!r.valid(r.ptr(at+40),4)))break;validIds.push(count);last=count+1;}if(last>=300)found.push({...p,base,count:last,validIds});}
 if(found.length!==1)return null;const p=found[0],expansion=itemExpansionProfile(r);if(expansion&&expansion.table===p.base){p.count=expansion.count;p.expansion=expansion;if(expansion.records!==null){p.format='segmented-classic';p.addresses=Array.from({length:p.count},(_,i)=>expandedItemAddress(r,expansion,i));p.validIds=[...p.validIds,...p.addresses.map((a,i)=>i>=expansion.ownedStart&&a>=0?i:null).filter(i=>i!==null)];}}trusted.set(p,r.bytes);return p;
}
export function readNativeItems(r,p){if(trusted.get(p)!==r.bytes)throw Error('Read the item layout from this ROM first.');return Array.from({length:p.count},(_,id)=>{const at=p.addresses?.[id]??p.base+id*44;if(!p.validIds.includes(id))return{id,name:'Unused item '+id,price:0,holdEffect:0,holdEffectParam:0,editable:false};return{id,name:decodeCreatureText(r.bytes,p.format!=='pointer-name'?at:r.ptr(at+p.name),p.format!=='pointer-name'?14:40)||'Unused item '+id,price:p.priceSize===2?r.u16(at+p.price):r.u32(at+p.price),holdEffect:p.format!=='pointer-name'?r.u8(at+18):0,holdEffectParam:p.format!=='pointer-name'?r.u8(at+19):0,descriptionAddress:r.ptr(at+p.description),pocket:p.format!=='pointer-name'?r.u8(at+26):0};});}
export function patchNativeItems(source,p,edits,output,encode){if(trusted.get(p)!==source)throw Error('Discover this ROM’s item table before writing.');const reports=[];for(const[idText,patch]of Object.entries(edits||{})){const id=Number(idText);if(!Number.isInteger(id)||id<1||id>=p.count||!p.validIds.includes(id))throw Error('Choose an existing nonempty item slot.');const at=p.addresses?.[id]??p.base+id*44;if(patch.price!==undefined){if(!Number.isInteger(patch.price)||patch.price<0||patch.price>(p.priceSize===2?65535:999999))throw Error('Invalid item price.');output.int(at+p.price,patch.price,p.priceSize);}if(patch.name!==undefined){const b=encode(patch.name);if(b.length>14)throw Error('Use an item name up to 13 characters.');if(p.format!=='pointer-name'){const n=new Uint8Array(14).fill(255);n.set(b);output.write(at,n);}else output.int(at+p.name,0x08000000+output.allocate(b,'Item name'));}if(p.format!=='pointer-name'){for(const[k,off]of[['holdEffect',18],['holdEffectParam',19]])if(patch[k]!==undefined){if(!Number.isInteger(patch[k])||patch[k]<0||patch[k]>255)throw Error('Invalid held-item effect.');output.write(at+off,Uint8Array.of(patch[k]));}}else if(patch.holdEffect||patch.holdEffectParam)throw Error('Held effects use another layout in this ROM.');reports.push('Item '+id);}return reports;}
const iconTables=new WeakMap();
export function discoverItemIcons(r,p){if(p.format==='pointer-name')return null;if(iconTables.has(r))return iconTables.get(r);const length=at=>{const q=r.ptr(at);return r.valid(q,4)&&r.u8(q)===16?r.u32(q)>>>8:-1;},found=[];for(let at=512;at<r.size-p.count*8;at+=4){if(length(at)!==288||length(at+4)!==32||length(at+8)!==288||length(at+12)!==32)continue;if(p.validIds.every(id=>length(at+id*8)===288&&length(at+id*8+4)===32))found.push(at);}const result=found.length===1?found[0]:null;iconTables.set(r,result);return result;}
